// Map each Tier A account to a region, an owner and a Slack channel, then build the message.
const REGIONS = {
  EMEA:     { owner: 'Lucía (EMEA BDR)',     channel: 'bdr-emea',     countries: ['ES','FR','DE','GB','NL','SE','LT','IE','IT','PT','BE','CH','AT','DK','NO','FI','PL','CZ','IL','AE'] },
  Americas: { owner: 'Jake (Americas BDR)',  channel: 'bdr-americas', countries: ['US','CA','MX','BR','AR','CL','CO','PE'] },
  APAC:     { owner: 'Mei (APAC BDR)',       channel: 'bdr-apac',     countries: ['AU','NZ','SG','JP','IN','HK','KR','CN'] },
};

return $input.all().map(item => {
  const a = item.json.body ?? item.json;          // Clay sends the row as the request body
  const v = k => (a[k] ?? '') === '' ? 'n/a' : a[k];   // never print "undefined" in Slack
  const country = (a.country || '').toUpperCase();
  const [region, r] = Object.entries(REGIONS).find(([, v]) => v.countries.includes(country))
                      ?? ['EMEA', REGIONS.EMEA];  // fallback so no alert is ever lost

  const text = [
    `:dart: *Tier A account: ${v('name')}* (${v('domain')})`,
    `*Owner:* ${r.owner}  ·  *Region:* ${region}`,
    `• *Why:* ${v('reason')}`,
    `• *Lookalike:* ${v('lookalike_score')}/100, most similar to ${v('nearest_customer')}`,
    `• *LLM confidence:* ${v('confidence')}  ·  *Headcount:* ${v('headcount')}  ·  *Country:* ${country || 'unknown'}`,
    `*Next step:* find the Head of Sales / RevOps and add them to the cadence.`,
  ].join('\n');

  return { json: { region, owner: r.owner, channel: r.channel, text, account: a } };
});
